<?php
// Phase 5 API integration tests: quotes, invoices, payments, schedules, payables, commissions, currencies, dashboard, reports, security, audit, idempotency.
declare(strict_types=1);
$base = rtrim($argv[1] ?? 'http://127.0.0.1:8000', '/') . '/api'; $results = []; $jars = []; $tok = [];
$cfg = require getenv('LTI_CONFIG'); $pdo = new PDO("mysql:host={$cfg['db']['host']};dbname={$cfg['db']['name']};charset=utf8mb4", $cfg['db']['user'], $cfg['db']['pass'], [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_EMULATE_PREPARES => false]);
$q = function ($sql) use ($pdo) { return $pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC); }; $one = function ($sql) use ($q) { $r = $q($sql); return $r ? array_values($r[0])[0] : null; };
function mk(string $who, string $method, string $path, $body = null, array $hdr = []) { global $base, $jars, $tok; $jars[$who] = $jars[$who] ?? tempnam(sys_get_temp_dir(), 'jar');
  $ch = curl_init($base . $path); $h = array_merge(['Accept: application/json'], $hdr); if (!empty($tok[$who]) && $method !== 'GET') $h[] = 'X-CSRF-Token: ' . $tok[$who];
  if ($body !== null) { $h[] = 'Content-Type: application/json'; curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($body)); }
  curl_setopt_array($ch, [CURLOPT_CUSTOMREQUEST => $method, CURLOPT_RETURNTRANSFER => true, CURLOPT_HTTPHEADER => $h, CURLOPT_COOKIEJAR => $jars[$who], CURLOPT_COOKIEFILE => $jars[$who], CURLOPT_HEADER => true]); return $ch; }
function done($ch): array { $res = curl_exec($ch) ?: curl_multi_getcontent($ch); $c = curl_getinfo($ch, CURLINFO_HTTP_CODE); $hs = curl_getinfo($ch, CURLINFO_HEADER_SIZE); $head = substr((string)$res, 0, $hs); $body = substr((string)$res, $hs); curl_close($ch);
  return [$c, json_decode($body, true) ?? [], $head, $body]; }
function req(string $who, string $m, string $p, $b = null, array $hdr = []): array { return done(mk($who, $m, $p, $b, $hdr)); }
function login(string $who, string $email): void { global $tok; [$c, $d] = req($who, 'POST', '/auth/login', ['email' => $email, 'password' => 'Dev-Password-2026']); if ($c !== 200) throw new Exception("login $email $c"); $tok[$who] = $d['csrf']; }
function t(string $n, callable $f): void { global $results; try { $results[] = [$n, true, (string)$f()]; } catch (Throwable $e) { $results[] = [$n, false, $e->getMessage()]; } }
function ok($c, string $m): void { if (!$c) throw new Exception($m); }
function rhu(int $num, int $den): int { $q = intdiv($num, $den); $r = $num % $den; return ($r * 2 >= $den) ? $q + 1 : $q; }   // independent half-up rounding for non-negative values
foreach (['own' => 'owner@lti.test', 'adm' => 'admin@lti.test', 'adv' => 'advisor@lti.test', 'adv2' => 'advisor2@lti.test', 'fin' => 'finance@lti.test', 'sal' => 'sales@lti.test', 'ops' => 'ops@lti.test', 'trv' => 'traveler@lti.test'] as $k => $e) login($k, $e);
$D = function (int $days) { return gmdate('Y-m-d', time() + $days * 86400); };
$amalfi = (int)$one("SELECT id FROM trips WHERE name='Amalfi Coast Anniversary'"); $shah = (int)$one("SELECT id FROM contacts WHERE email='shah@example.com'"); $advId = (int)$one("SELECT id FROM users WHERE email='advisor@lti.test'"); $S = [];
// ---------------- quotes ----------------
t('TC01 Create quote; MySQL record', function () use (&$S, $amalfi, $one) { [$c, $d] = req('adv', 'POST', '/quotes', ['tripId' => $amalfi, 'title' => 'Amalfi anniversary package', 'currency' => 'USD', 'validUntil' => '2027-06-30', 'terms' => 'Prices subject to availability until booked.', 'lines' => [['description' => 'Le Sirenuse, sea-view room (per night)', 'quantity' => '2', 'unitPrice' => '1350.00']], 'total' => '1.00']);
  ok($c === 201, "$c " . json_encode($d)); $S['q'] = $d['quote']['id']; $r = $one("SELECT CONCAT_WS('|',number,status,currency,total,trip_id) FROM quotations WHERE id={$S['q']}"); ok(preg_match('/^Q-\d{4}-\d{5}\|draft\|USD\|2700\.00\|' . $amalfi . '$/', $r) === 1, $r); return $r . ' (client-sent total ignored)'; });
t('TC02 Edit draft quote; persists; stale version 409', function () use (&$S, $one) { [, $g] = req('adv', 'GET', "/quotes/{$S['q']}"); [$c] = req('adv', 'PUT', "/quotes/{$S['q']}", ['title' => 'Amalfi anniversary — 8 nights', 'validUntil' => '2027-07-15', 'version' => $g['quote']['version']]);
  [$c2] = req('adv', 'PUT', "/quotes/{$S['q']}", ['title' => 'stale', 'version' => $g['quote']['version']]); ok($c === 200 && $c2 === 409 && $one("SELECT CONCAT(title,'|',valid_until) FROM quotations WHERE id={$S['q']}") === 'Amalfi anniversary — 8 nights|2027-07-15', "$c $c2"); return 'saved'; });
t('TC03–TC04 Multiple line items; server-side subtotal and total', function () use (&$S, $one) { [$c, $d] = req('adv', 'PUT', "/quotes/{$S['q']}", ['lines' => [['description' => 'Le Sirenuse (per night)', 'quantity' => '2', 'unitPrice' => '1350.00'], ['description' => 'Capri boat day', 'quantity' => '1', 'unitPrice' => '480.50'], ['description' => 'Limoncello tasting (per person)', 'quantity' => '3', 'unitPrice' => '33.33', 'taxable' => false]], 'subtotal' => '9.99']);
  $exp = 2 * 135000 + 48050 + 3 * 3333; ok($c === 200 && (int)$one("SELECT COUNT(*) FROM document_lines WHERE quotation_id={$S['q']}") === 3 && $one("SELECT CONCAT(subtotal,'|',total) FROM quotations WHERE id={$S['q']}") === sprintf('%.2f|%.2f', $exp / 100, $exp / 100), json_encode($d['quote'] ?? $d)); return '3 lines; subtotal ' . sprintf('%.2f', $exp / 100); });
t('TC05 Discount and configured tax computed on the server; invalid values rejected', function () use (&$S, $one) { [$c0, $tx] = req('own', 'POST', '/finance/tax-rates', ['name' => 'Sales tax', 'rate' => '8.25']); $S['tax'] = $tx['taxRate']['id'];
  [$c] = req('adv', 'PUT', "/quotes/{$S['q']}", ['discountType' => 'percent', 'discountValue' => '10', 'taxRateId' => $S['tax']]);
  $sub = 328049; $disc = rhu($sub * 100000, 1000000); $taxable = 318050; $dt = rhu($disc * $taxable, $sub); $tax = rhu(($taxable - $dt) * 82500, 1000000); $total = $sub - $disc + $tax;
  $row = $one("SELECT CONCAT_WS('|',discount_total,tax_total,total,tax_name,tax_rate) FROM quotations WHERE id={$S['q']}");
  [$c2] = req('adv', 'PUT', "/quotes/{$S['q']}", ['discountType' => 'percent', 'discountValue' => '120']); [$c3] = req('adv', 'PUT', "/quotes/{$S['q']}", ['discountType' => 'fixed', 'discountValue' => '99999']); [$c4] = req('adv', 'PUT', "/quotes/{$S['q']}", ['lines' => [['description' => 'x', 'quantity' => '1', 'unitPrice' => '10.005']]]);
  ok($c0 === 201 && $c === 200 && $row === sprintf('%.2f|%.2f|%.2f|Sales tax|8.2500', $disc / 100, $tax / 100, $total / 100) && $c2 === 422 && $c3 === 422 && $c4 === 422, "$row $c2 $c3 $c4"); $S['qTotal'] = sprintf('%.2f', $total / 100); return "discount {$disc}, tax {$tax}, total {$S['qTotal']} (independently computed); bad values 422"; });
t('TC06 Send and accept; immutable snapshot preserved; accepted quote cannot be edited', function () use (&$S, $one) { [$c1] = req('adv', 'POST', "/quotes/{$S['q']}/send", ['channel' => 'Emailed from advisor mailbox']); [$c2, $d] = req('adv', 'POST', "/quotes/{$S['q']}/decision", ['decision' => 'accepted', 'clientName' => 'Daniel Shah', 'note' => 'Confirmed by phone']);
  [$c3] = req('adv', 'PUT', "/quotes/{$S['q']}", ['title' => 'tamper']); req('own', 'PUT', "/finance/tax-rates/{$S['tax']}", ['isActive' => false]);
  $snap = json_decode($one("SELECT snapshot_json FROM quote_acceptances WHERE quote_id={$S['q']}"), true); $sha = $one("SELECT snapshot_sha256 FROM quote_acceptances WHERE quote_id={$S['q']}");
  ok($c1 === 200 && $c2 === 200 && $c3 === 409 && $snap['total'] === $S['qTotal'] && count($snap['lines']) === 3 && $sha === hash('sha256', $one("SELECT snapshot_json FROM quote_acceptances WHERE quote_id={$S['q']}")) && $one("SELECT total FROM quotations WHERE id={$S['q']}") === $S['qTotal'] && strpos($d['quote']['decision']['method'], 'not a digital signature') !== false, "$c1 $c2 $c3");
  return 'snapshot total ' . $snap['total'] . ' with SHA-256; edit 409; tax rate change does not alter it'; });
t('TC07 + TC35 Convert accepted quote to invoice from the snapshot; repeat conversions blocked or replayed', function () use (&$S, $one) { $k = 'conv-' . bin2hex(random_bytes(6));
  [$c, $d] = req('adv', 'POST', "/quotes/{$S['q']}/convert", null, ["Idempotency-Key: $k"]); [$c2, $d2, $h2] = req('adv', 'POST', "/quotes/{$S['q']}/convert", null, ["Idempotency-Key: $k"]); [$c3] = req('adv', 'POST', "/quotes/{$S['q']}/convert");
  $S['invA'] = $d['invoice']['id']; ok($c === 200 && $d['invoice']['total'] === $S['qTotal'] && $d['invoice']['quoteId'] === $S['q'] && $c2 === 200 && stripos($h2, 'Idempotent-Replay: true') !== false && $d2['invoice']['id'] === $S['invA'] && $c3 === 409 && (int)$one("SELECT COUNT(*) FROM invoices WHERE quote_id={$S['q']}") === 1, "$c $c2 $c3");
  return "invoice {$S['invA']} total {$S['qTotal']}; replay returned same invoice; new attempt 409; 1 invoice in MySQL"; });
t('TC08 Standalone invoice (EUR, contact only)', function () use (&$S, $shah, $one) { [$c, $d] = req('adv', 'POST', '/invoices', ['contactId' => $shah, 'currency' => 'EUR', 'dueDate' => '2027-03-01', 'paymentTerms' => 'Net 30', 'lines' => [['description' => 'Rome private guide', 'quantity' => '2', 'unitPrice' => '600.00'], ['description' => 'Vatican early entry', 'quantity' => '4', 'unitPrice' => '75.00']]]);
  ok($c === 201 && $d['invoice']['total'] === '1500.00' && $d['invoice']['status'] === 'draft', "$c " . json_encode($d)); $S['invB'] = $d['invoice']['id']; return "invoice {$S['invB']} EUR 1500.00 draft"; });
t('TC09 Unique invoice numbers, including concurrent issue requests', function () use (&$S, $shah, $one) { [$c1, $a] = req('adv', 'POST', "/invoices/{$S['invA']}/issue", ['dueDate' => '2026-12-01']); [$c2, $b] = req('adv', 'POST', "/invoices/{$S['invB']}/issue", ['dueDate' => '2027-03-01']); [$c3] = req('adv', 'POST', "/invoices/{$S['invA']}/issue", ['dueDate' => '2026-12-01']);
  [, $x] = req('adv', 'POST', '/invoices', ['contactId' => $shah, 'currency' => 'USD', 'dueDate' => '2027-01-01', 'lines' => [['description' => 'Concurrency check', 'unitPrice' => '1']]]); $xid = $x['invoice']['id'];
  $mh = curl_multi_init(); $hs = [mk('adv', 'POST', "/invoices/$xid/issue", ['dueDate' => '2027-01-01']), mk('adv', 'POST', "/invoices/$xid/issue", ['dueDate' => '2027-01-01'])]; foreach ($hs as $h) curl_multi_add_handle($mh, $h); do { curl_multi_exec($mh, $run); curl_multi_select($mh); } while ($run);
  $codes = array_map(function ($h) { $c = curl_getinfo($h, CURLINFO_HTTP_CODE); return $c; }, $hs); sort($codes);
  $nums = array_column($GLOBALS['q']("SELECT number FROM invoices WHERE number LIKE 'INV-%'"), 'number'); ok($c1 === 200 && $c2 === 200 && $c3 === 409 && $a['invoice']['number'] !== $b['invoice']['number'] && count($nums) === count(array_unique($nums)) && count($nums) === 3 && $codes === [200, 409], json_encode([$c1, $c2, $c3, $codes, $nums]));
  return implode(', ', $nums) . '; parallel issue: ' . implode('/', $codes); });
t('TC10–TC12 Partial payment, outstanding balance, final payment marks paid', function () use (&$S, $one, $D) { [$c, $d] = req('fin', 'POST', '/payments', ['invoiceId' => $S['invA'], 'amount' => '1000.00', 'method' => 'bank_transfer', 'reference' => 'Wire ref 7781', 'receivedOn' => $D(-2)]);
  $total = (int)round((float)$S['qTotal'] * 100); $bal = $total - 100000; ok($c === 201 && $d['invoice']['status'] === 'partially_paid' && $d['invoice']['balance'] === sprintf('%.2f', $bal / 100) && $d['payment']['verification'] === 'unverified', "$c " . json_encode($d['invoice'] ?? $d));
  [$c2, $d2] = req('fin', 'POST', '/payments', ['invoiceId' => $S['invA'], 'amount' => sprintf('%.2f', $bal / 100), 'method' => 'card_external', 'reference' => 'Card ending 4417', 'receivedOn' => $D(-1)]); $S['finalPay'] = $d2['payment']['id'];
  ok($c2 === 201 && $d2['invoice']['status'] === 'paid' && $d2['invoice']['balance'] === '0.00' && $one("SELECT CONCAT(status,'|',balance,'|',amount_paid) FROM invoices WHERE id={$S['invA']}") === 'paid|0.00|' . $S['qTotal'], json_encode($d2['invoice'] ?? $d2)); return 'balance after partial ' . sprintf('%.2f', $bal / 100) . '; paid after final; payments marked unverified'; });
t('TC13 Overpayment, draft, currency mismatch and card numbers rejected', function () use (&$S, $shah) { [$c1, $e1] = req('fin', 'POST', '/payments', ['invoiceId' => $S['invB'], 'amount' => '1500.01', 'method' => 'cash']); [, $x] = req('adv', 'POST', '/invoices', ['contactId' => $shah, 'currency' => 'USD', 'lines' => [['description' => 'Draft', 'unitPrice' => '5']]]);
  [$c2] = req('fin', 'POST', '/payments', ['invoiceId' => $x['invoice']['id'], 'amount' => '1', 'method' => 'cash']); [$c3] = req('fin', 'POST', '/payments', ['invoiceId' => $S['invB'], 'amount' => '10', 'currency' => 'USD', 'method' => 'cash']);
  [$c4] = req('fin', 'POST', '/payments', ['invoiceId' => $S['invB'], 'amount' => '10', 'method' => 'card_external', 'reference' => '4111 1111 1111 1111']); [$c5] = req('fin', 'POST', '/payments', ['invoiceId' => $S['invA'], 'amount' => '1', 'method' => 'cash']);
  ok($c1 === 422 && strpos($e1['error'], 'exceeds the outstanding balance') !== false && $c2 === 409 && $c3 === 422 && $c4 === 422 && $c5 === 422, "$c1 $c2 $c3 $c4 $c5"); return 'overpay 422; draft 409; wrong currency 422; card number 422; paid invoice 422'; });
t('TC14 Reverse payment; balance recalculated; reason required; audited', function () use (&$S, $one) { [$c0] = req('fin', 'POST', "/payments/{$S['finalPay']}/reverse", []); [$c1] = req('adv', 'POST', "/payments/{$S['finalPay']}/reverse", ['reason' => 'x']); [$c, $d] = req('fin', 'POST', "/payments/{$S['finalPay']}/reverse", ['reason' => 'Card chargeback reported by client']);
  $total = (int)round((float)$S['qTotal'] * 100); ok($c0 === 422 && $c1 === 403 && $c === 200 && $d['invoice']['status'] === 'partially_paid' && $d['invoice']['balance'] === sprintf('%.2f', ($total - 100000) / 100) && $one("SELECT reason FROM financial_audit_events WHERE action='payment.reversed' AND entity_id={$S['finalPay']}") === 'Card chargeback reported by client', "$c0 $c1 $c");
  return 'balance restored to ' . $d['invoice']['balance'] . '; advisor 403; no reason 422'; });
t('TC15–TC16 Installment schedule must reconcile; allocations never double count', function () use (&$S, $one, $D) { [$c0] = req('fin', 'PUT', "/invoices/{$S['invB']}/schedule", ['installments' => [['label' => 'Deposit', 'amount' => '450.00', 'dueDate' => $D(14), 'isDeposit' => true], ['amount' => '500.00', 'dueDate' => $D(60)]]]);
  [$c, $d] = req('fin', 'PUT', "/invoices/{$S['invB']}/schedule", ['installments' => [['label' => 'Deposit', 'amount' => '450.00', 'dueDate' => $D(14), 'isDeposit' => true], ['amount' => '525.00', 'dueDate' => $D(60)], ['amount' => '525.00', 'dueDate' => $D(90)]], 'reason' => 'Agreed with client']);
  [, $p1] = req('fin', 'POST', '/payments', ['invoiceId' => $S['invB'], 'amount' => '600.00', 'method' => 'bank_transfer', 'receivedOn' => $D(-3)]); [, $p2] = req('fin', 'POST', '/payments', ['invoiceId' => $S['invB'], 'amount' => '100.00', 'method' => 'cash', 'receivedOn' => $D(-2)]);
  $alloc = $one("SELECT SUM(a.amount) FROM payment_allocations a JOIN payment_schedules s ON s.id=a.installment_id WHERE s.invoice_id={$S['invB']}"); $st = $one("SELECT GROUP_CONCAT(status ORDER BY due_date) FROM payment_schedules WHERE invoice_id={$S['invB']}");
  req('fin', 'POST', '/payments/' . $p2['payment']['id'] . '/reverse', ['reason' => 'Duplicate entry']); req('fin', 'POST', '/payments/' . $p1['payment']['id'] . '/refunds', ['amount' => '50.00', 'reason' => 'Fee refund', 'method' => 'bank_transfer']);
  $alloc2 = $one("SELECT SUM(a.amount) FROM payment_allocations a JOIN payment_schedules s ON s.id=a.installment_id WHERE s.invoice_id={$S['invB']}"); $paid = $one("SELECT amount_paid FROM invoices WHERE id={$S['invB']}");
  ok($c0 === 422 && $c === 200 && $alloc === '700.00' && $st === 'paid,partially_paid,scheduled' && $alloc2 === '550.00' && $paid === '550.00', "$c0 $c alloc=$alloc st=$st alloc2=$alloc2 paid=$paid"); return 'mismatch 422; allocations 700.00 then 550.00 after reversal and refund = amount paid'; });
// ---------------- payables ----------------
t('TC17 Create supplier payable from a booking; duplicate reference refused', function () use (&$S, $amalfi, $one) { [, $s] = req('ops', 'POST', '/suppliers', ['name' => 'Hotel Santa Caterina', 'category' => 'hotel']); $S['sup'] = $s['supplier']['id'];
  [, $b] = req('own', 'POST', '/bookings', ['tripId' => $amalfi, 'supplierId' => $S['sup'], 'category' => 'accommodation', 'amount' => '5400.00', 'supplierCost' => '4700.00', 'startDate' => '2026-12-03']); $S['bk'] = $b['booking']['id'];
  [$c, $d] = req('fin', 'POST', '/payables', ['bookingId' => $S['bk'], 'supplierInvoiceRef' => 'HSC-INV-2201', 'dueDate' => '2026-11-20']); [$c2] = req('fin', 'POST', '/payables', ['bookingId' => $S['bk'], 'supplierInvoiceRef' => 'HSC-INV-2201']);
  ok($c === 201 && $d['payable']['amount'] === '4700.00' && $d['payable']['currency'] === 'USD' && $c2 === 409, "$c $c2 " . json_encode($d)); $S['pay'] = $d['payable']['id']; return "payable {$S['pay']} 4700.00 from supplier cost; duplicate 409"; });
t('TC18–TC19 Partial supplier payment; outstanding balance; overpayment refused; reversal restores', function () use (&$S, $one, $D) { [$c, $d] = req('fin', 'POST', "/payables/{$S['pay']}/payments", ['amount' => '2000.00', 'paidOn' => $D(-1), 'reference' => 'Wire 5512']);
  [$c2] = req('fin', 'POST', "/payables/{$S['pay']}/payments", ['amount' => '2700.01']); $pid = $d['payable']['payments'][0]['id']; [$c3, $d3] = req('fin', 'POST', "/supplier-payments/$pid/reverse", ['reason' => 'Sent to wrong account']); [$c4, $d4] = req('fin', 'POST', "/payables/{$S['pay']}/payments", ['amount' => '2000.00', 'reference' => 'Wire 5513']);
  ok($c === 200 && $d['payable']['status'] === 'partially_paid' && $d['payable']['balance'] === '2700.00' && $c2 === 422 && $d3['payable']['balance'] === '4700.00' && $d4['payable']['balance'] === '2700.00' && $one("SELECT balance FROM supplier_payables WHERE id={$S['pay']}") === '2700.00', "$c $c2 $c3 $c4"); return 'balance 2700.00; overpay 422; reversal back to 4700.00'; });
// ---------------- commissions ----------------
t('TC20 Percentage commission rule calculated on the server', function () use (&$S, $advId) { [$c0, $r] = req('fin', 'POST', '/commission-rules', ['name' => 'Default 10%', 'basis' => 'percent', 'value' => '10', 'advisorSharePct' => '50']);
  [$c, $d] = req('own', 'POST', "/bookings/{$S['bk']}/commission", ['advisorId' => $advId]); $S['cm'] = $d['commission']['id'];
  ok($c0 === 201 && $c === 200 && $d['commission']['agencyExpected'] === '540.00' && $d['commission']['advisorAmount'] === '270.00' && $d['commission']['status'] === 'expected', "$c0 $c " . json_encode($d)); return '10% of 5400.00 = 540.00; advisor 50% = 270.00'; });
t('TC21 Flat-amount supplier rule wins over the default; currency-specific', function () use (&$S, $amalfi) { req('fin', 'POST', '/commission-rules', ['name' => 'Santa Caterina flat', 'basis' => 'flat', 'value' => '250.00', 'currency' => 'USD', 'supplierId' => $S['sup'], 'advisorSharePct' => '40']);
  [, $b] = req('own', 'POST', '/bookings', ['tripId' => $amalfi, 'supplierId' => $S['sup'], 'category' => 'dining', 'amount' => '900.00']); $S['bk2'] = $b['booking']['id']; [$c, $d] = req('own', 'POST', "/bookings/{$S['bk2']}/commission"); $S['cm2'] = $d['commission']['id'];
  ok($c === 200 && $d['commission']['agencyExpected'] === '250.00' && $d['commission']['basis'] === 'flat' && $d['commission']['advisorAmount'] === '100.00', "$c " . json_encode($d)); return 'flat 250.00; advisor 40% = 100.00'; });
t('TC22 Commission linked to booking and advisor; advisors see only their own', function () use (&$S, $advId) { [, $l] = req('fin', 'GET', "/commissions?advisorId=$advId"); [, $mine] = req('adv', 'GET', '/commissions'); [, $other] = req('adv2', 'GET', '/commissions'); [$c3] = req('adv2', 'GET', "/commissions/{$S['cm']}");
  ok(in_array($S['cm'], array_column($l['items'], 'id'), true) && array_column($mine['items'], 'id') === [$S['cm']] && count($other['items']) === 0 && $c3 === 404 && $l['items'][0]['bookingId'] === $S['bk'], json_encode([array_column($mine['items'], 'id'), count($other['items']), $c3])); return 'filter by advisor; advisor sees own only; other advisor 404'; });
t('TC23 Agency receipt and advisor payout recorded separately', function () use (&$S, $one, $D) { [$c0] = req('fin', 'POST', "/commissions/{$S['cm']}/payouts", ['amount' => '270.00']); [$c1, $d1] = req('fin', 'POST', "/commissions/{$S['cm']}/receipts", ['amount' => '540.00', 'receivedOn' => $D(-1), 'reference' => 'Supplier statement 11/26']);
  [$c2] = req('fin', 'POST', "/commissions/{$S['cm']}/payouts", ['amount' => '270.01']); [$c3] = req('adv', 'POST', "/commissions/{$S['cm']}/payouts", ['amount' => '10']); [$c4, $d4] = req('fin', 'POST', "/commissions/{$S['cm']}/payouts", ['amount' => '270.00', 'reference' => 'Payroll Nov']);
  ok($c0 === 409 && $c1 === 200 && $d1['commission']['status'] === 'payable' && $c2 === 422 && $c3 === 403 && $c4 === 200 && $d4['commission']['status'] === 'paid' && (int)$one("SELECT COUNT(*) FROM commission_receipts WHERE commission_id={$S['cm']}") === 1 && (int)$one("SELECT COUNT(*) FROM advisor_payouts WHERE commission_id={$S['cm']}") === 1, "$c0 $c1 $c2 $c3 $c4");
  return 'payout before receipt 409; receipt -> payable; over-payout 422; advisor 403; payout -> paid'; });
t('TC24 Commission reversal: automatic on booking cancellation; blocked while payouts exist', function () use (&$S, $one) { req('own', 'POST', "/bookings/{$S['bk2']}/cancel", ['reason' => 'Client cancelled dinner']); $st2 = $one("SELECT CONCAT(status,'|',reversal_reason) FROM commissions WHERE id={$S['cm2']}");
  [$c1] = req('fin', 'POST', "/commissions/{$S['cm']}/reverse", ['reason' => 'Supplier clawback']); $po = (int)$one("SELECT id FROM advisor_payouts WHERE commission_id={$S['cm']}"); $rc = (int)$one("SELECT id FROM commission_receipts WHERE commission_id={$S['cm']}");
  [$c2] = req('fin', 'POST', "/advisor-payouts/$po/reverse", ['reason' => 'Clawback from payroll']); [$c3] = req('fin', 'POST', "/commission-receipts/$rc/reverse", ['reason' => 'Supplier clawback']); [$c4, $d4] = req('fin', 'POST', "/commissions/{$S['cm']}/reverse", ['reason' => 'Supplier clawback']);
  ok($st2 === 'reversed|Booking cancelled' && $c1 === 409 && $c2 === 200 && $c3 === 200 && $c4 === 200 && $d4['commission']['status'] === 'reversed', "$st2 $c1 $c2 $c3 $c4"); return 'auto-reversed on cancel; manual reversal requires payouts and receipts to be reversed first'; });
