t('TC25 Multi-currency: minor units enforced, totals per currency, explicit manual conversion', function () use (&$S, $shah, $one) { [$c1] = req('adv', 'POST', '/invoices', ['contactId' => $shah, 'currency' => 'JPY', 'lines' => [['description' => 'Kyoto ryokan', 'unitPrice' => '45000.5']]]);
  [$c2, $j] = req('adv', 'POST', '/invoices', ['contactId' => $shah, 'currency' => 'JPY', 'dueDate' => '2027-04-01', 'lines' => [['description' => 'Kyoto ryokan', 'quantity' => '3', 'unitPrice' => '45000'], ['description' => 'Tea ceremony', 'quantity' => '1.5', 'unitPrice' => '7333']]]);
  [$c3, $k] = req('adv', 'POST', '/invoices', ['contactId' => $shah, 'currency' => 'KWD', 'lines' => [['description' => 'Desert camp', 'quantity' => '3', 'unitPrice' => '33.335']]]); [$c4] = req('adv', 'POST', '/invoices', ['contactId' => $shah, 'currency' => 'XYZ', 'lines' => [['description' => 'x', 'unitPrice' => '1']]]);
  req('adv', 'POST', '/invoices/' . $j['invoice']['id'] . '/issue', []); [$c5] = req('fin', 'POST', '/finance/rates', ['fromCurrency' => 'EUR', 'toCurrency' => 'USD', 'rate' => '1.08', 'effectiveDate' => '2026-11-01', 'sourceNote' => 'Bank of record daily rate']); [$c6] = req('adv', 'POST', '/finance/rates', ['fromCurrency' => 'EUR', 'toCurrency' => 'GBP', 'rate' => '0.85', 'sourceNote' => 'x']);
  [, $dash] = req('fin', 'GET', '/finance/dashboard?from=2026-01-01&to=2027-12-31'); $inv = $dash['metrics']['invoiced']; $usd = (int)round((float)$inv['byCurrency']['USD'] * 100); $eur = (int)round((float)$inv['byCurrency']['EUR'] * 100); $expConv = $usd + rhu($eur * 108, 100);
  ok($c1 === 422 && $c2 === 201 && $j['invoice']['total'] === '146000' && $c3 === 422 && $c4 === 422 && $c5 === 201 && $c6 === 403 && $inv['converted']['total'] === sprintf('%.2f', $expConv / 100) && in_array('JPY', $inv['converted']['missingRates'], true), json_encode([$c1, $c2, $j['invoice']['total'] ?? '', $c3, $k['invoice']['total'] ?? '', $c4, $c5, $c6, $inv]));
  return 'JPY 146000 shown with 0 decimals (1.5 x 7333 = 10999.5 rounds half-up); fractional yen 422; KWD (3-decimal) refused as unsupported; USD + EUR x 1.08 = ' . $inv['converted']['total'] . '; JPY listed as missing a rate'; });
t('TC26 Dashboard figures equal direct MySQL totals', function () use (&$S, $one) { [$c, $d] = req('fin', 'GET', '/finance/dashboard?from=2026-01-01&to=2027-12-31'); $m = $d['metrics'];
  $inv = $one("SELECT SUM(total+adjustments_total) FROM invoices WHERE currency='USD' AND status IN ('issued','partially_paid','paid') AND issue_date BETWEEN '2026-01-01' AND '2027-12-31'"); $rec = $one("SELECT SUM(balance) FROM invoices WHERE currency='EUR' AND status IN ('issued','partially_paid')");
  $pay = $one("SELECT SUM(balance) FROM supplier_payables WHERE status IN ('open','partially_paid')"); $paid = $one("SELECT (SELECT SUM(amount) FROM payments WHERE currency='EUR' AND status='recorded') - (SELECT SUM(r.amount) FROM refunds r JOIN payments p ON p.id=r.payment_id WHERE p.currency='EUR' AND p.status='recorded')");
  ok($c === 200 && $m['invoiced']['byCurrency']['USD'] === $inv && $m['receivables']['byCurrency']['EUR'] === $rec && $m['payables']['byCurrency']['USD'] === $pay && $m['paymentsRecorded']['byCurrency']['EUR'] === $paid && isset($m['invoiced']['definition']), json_encode([$m['invoiced']['byCurrency'], $inv, $m['receivables']['byCurrency'], $rec, $m['payables']['byCurrency'], $pay, $m['paymentsRecorded']['byCurrency'], $paid]));
  return "invoiced USD $inv, receivables EUR $rec, payables USD $pay, payments EUR $paid all match SQL"; });
t('TC27 Invoice aging and commission reports export as CSV', function () use (&$S) { [$c, , $h, $csv] = req('fin', 'GET', '/finance/reports?name=aging&format=csv'); [$c2, , $h2, $csv2] = req('fin', 'GET', '/finance/reports?name=commissions&format=csv&from=2026-01-01&to=2027-12-31');
  [$c3, $j] = req('fin', 'GET', '/finance/reports?name=quotes&from=2026-01-01&to=2027-12-31'); $nb = $GLOBALS['one']("SELECT number FROM invoices WHERE id={$S['invA']}"); $bk = $GLOBALS['one']("SELECT reference FROM bookings WHERE id={$S['bk']}");
  ok($c === 200 && stripos($h, 'text/csv') !== false && strpos($csv, $nb) !== false && strpos($csv, 'not an audited accounting statement') !== false && $c2 === 200 && strpos($csv2, $bk) !== false && $c3 === 200 && $j['rows'][0]['Accepted'] == 1, "$c $c2 $c3"); return "aging CSV contains $nb; commission CSV contains $bk; quote conversion report"; });
t('TC28 Restricted financial access enforced on the server', function () use (&$S) { $r = [];
  [$r['sales invoices']] = req('sal', 'GET', '/invoices'); [$r['advisor2 invoice']] = req('adv2', 'GET', "/invoices/{$S['invA']}"); [$r['advisor2 print']] = req('adv2', 'GET', "/invoices/{$S['invA']}/print"); [$r['advisor void']] = req('adv', 'POST', "/invoices/{$S['invB']}/void", ['reason' => 'x']);
  [$r['advisor rule']] = req('adv', 'POST', '/commission-rules', ['name' => 'x', 'basis' => 'percent', 'value' => '5']); [$r['traveler dashboard']] = req('trv', 'GET', '/finance/dashboard'); [$r['sales report']] = req('sal', 'GET', '/finance/reports?name=payments&format=csv'); [$r['advisor audit']] = req('adv', 'GET', '/finance/audit');
  [, $rep] = req('adv2', 'GET', '/finance/reports?name=aging'); $r['advisor2 aging rows'] = count($rep['rows']);
  $exp = ['sales invoices' => 403, 'advisor2 invoice' => 404, 'advisor2 print' => 404, 'advisor void' => 403, 'advisor rule' => 403, 'traveler dashboard' => 403, 'sales report' => 403, 'advisor audit' => 403, 'advisor2 aging rows' => 0];
  ok($r == $exp, json_encode($r)); return json_encode($r); });
t('TC29 Financial records persist across a new session', function () use (&$S) { login('fin2', 'finance@lti.test'); [, $a] = req('fin2', 'GET', "/invoices/{$S['invA']}"); [, $b] = req('fin2', 'GET', "/invoices/{$S['invB']}");
  ok($a['invoice']['status'] === 'partially_paid' && count($a['invoice']['payments']) === 2 && $b['invoice']['amountPaid'] === '550.00' && count($b['invoice']['installments']) === 3, json_encode([$a['invoice']['status'] ?? '', $b['invoice']['amountPaid'] ?? ''])); return 'new session reads the same balances, payments and schedule'; });
t('TC30 Reversals and adjustments are audit-logged in a tamper-evident chain', function () use (&$S, $pdo, $one) { [$c] = req('fin', 'POST', "/invoices/{$S['invB']}/adjustments", ['amount' => '-25.00', 'reason' => 'Goodwill credit for late transfer']);
  $acts = array_column($GLOBALS['q']("SELECT DISTINCT action FROM financial_audit_events"), 'action'); foreach (['payment.reversed', 'invoice.adjusted', 'commission.reversed', 'commission.payout_reversed', 'commission.receipt_reversed', 'payable.payment_reversed', 'quote.accepted', 'invoice.issued'] as $x) ok(in_array($x, $acts, true), "missing $x");
  [, $v1] = req('adm', 'GET', '/finance/audit/verify'); $id = (int)$one("SELECT MIN(id) FROM financial_audit_events WHERE action='payment.reversed'"); $orig = $one("SELECT reason FROM financial_audit_events WHERE id=$id");
  $pdo->exec("UPDATE financial_audit_events SET reason='edited quietly' WHERE id=$id"); [, $v2] = req('adm', 'GET', '/finance/audit/verify'); $st = $pdo->prepare('UPDATE financial_audit_events SET reason=? WHERE id=?'); $st->execute([$orig, $id]); [, $v3] = req('adm', 'GET', '/finance/audit/verify');
  ok($c === 200 && $v1['valid'] === true && $v2['valid'] === false && $v2['brokenAt'] === $id && $v3['valid'] === true, json_encode([$c, $v1, $v2, $v3])); return "chain of {$v1['checked']} events valid; a direct SQL edit is detected at event $id"; });
t('TC35 Repeated payment submissions are not duplicated', function () use (&$S, $one) { $k = 'pay-' . bin2hex(random_bytes(6)); $body = ['invoiceId' => $S['invB'], 'amount' => '10.00', 'method' => 'cash', 'reference' => 'Counter receipt 88'];
  [$c1, $d1] = req('fin', 'POST', '/payments', $body, ["Idempotency-Key: $k"]); [$c2, $d2, $h2] = req('fin', 'POST', '/payments', $body, ["Idempotency-Key: $k"]); [$c3] = req('fin', 'POST', '/payments', array_merge($body, ['amount' => '11.00']), ["Idempotency-Key: $k"]);
  $mh = curl_multi_init(); $k2 = 'pay-' . bin2hex(random_bytes(6)); $hs = [mk('fin', 'POST', '/payments', $body, ["Idempotency-Key: $k2"]), mk('fin', 'POST', '/payments', $body, ["Idempotency-Key: $k2"])]; foreach ($hs as $h) curl_multi_add_handle($mh, $h); do { curl_multi_exec($mh, $run); curl_multi_select($mh); } while ($run);
  $codes = array_map(function ($h) { return curl_getinfo($h, CURLINFO_HTTP_CODE); }, $hs); sort($codes); $n = (int)$one("SELECT COUNT(*) FROM payments WHERE reference='Counter receipt 88' AND status='recorded'");
  ok($c1 === 201 && $c2 === 200 && stripos($h2, 'Idempotent-Replay: true') !== false && $d2['payment']['id'] === $d1['payment']['id'] && $c3 === 422 && $n === 2 && in_array($codes, [[201, 409], [200, 201], [201, 201]], true) , json_encode([$c1, $c2, $c3, $codes, $n]));
  return 'replay returned the same payment; changed body with same key 422; parallel duplicates ' . implode('/', $codes) . '; exactly one row per key'; });
$pass = count(array_filter($results, function ($r) { return $r[1]; })); foreach ($results as [$n, $o, $d]) echo ($o ? 'PASS ' : 'FAIL ') . "$n — $d\n";
echo "PHASE5 API SUMMARY $pass/" . count($results) . "\n"; file_put_contents(__DIR__ . '/api_phase5_results.json', json_encode($results, JSON_PRETTY_PRINT)); exit($pass === count($results) ? 0 : 1);
